#include <bits/stdc++.h>
using namespace std;

int main() {
  ios::sync_with_stdio(false); cin.tie(nullptr);
  int n,m; cin>>n>>m; vector<string> a(n); for(auto &s:a) cin>>s;
  queue<tuple<int,int,int>> q; set<pair<int,int>> seen;
  if(a[0][0]=='1') {q.push({0,0,1}); seen.insert({0,0});}
  int ans=-1; int dx[]={1,-1,0,0},dy[]={0,0,1,-1};
  while(!q.empty()){auto [x,y,d]=q.front(); q.pop();
    if(x==n-1 && y==m-1){ans=d; break;}
    for(int k=0;k<4;k++){int nx=x+dx[k],ny=y+dy[k];
      if(nx>=0 && nx<n && ny>=0 && ny<m && a[nx][ny]=='1' && !seen.count({nx,ny})) {seen.insert({nx,ny}); q.push({nx,ny,d+1});}
    }
  } cout<<ans;
}

